INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_cafdb33','service_pool_022','海河边上',3,'半天起订，超时按小时加钱。楼门口有台阶，推车或者行动不便的同事要注意。','签到桌','2026-05-25T11:09:53+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_c377ba6','venue_pottery_023','爱喝茶的程序员',4,'只能开材料销售的发票，我们财务不认，最后自己贴的。门口不好停车，我们停到隔壁写字楼地库了，两小时十块。',NULL,'2026-06-03T16:53:56+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_af21232','venue_pottery_023','预算有限',3,'主讲老师讲了十分钟历史，实操时间被压缩了。场地标称容纳三十人，但算上放包和作品架，二十五人就已经很满。','场地全景','2026-06-03T18:58:38+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_u66e95c','venue_pottery_024','HR老王',4,'开票金额和实际付款差了几十块说是优惠券不能开票。烧制排期赶上旺季，往后延了一周。餐盒标签写了含麸质，过敏的同事提前避开了。周末散客和团队混在一起，声音有点吵，建议工作日包场。',NULL,'2026-06-18T09:59:41+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_z090c77','venue_pottery_024','老张头',3,'开票要等一周，催了两次才拿到。烧制排期赶上旺季，往后延了一周。两个老师带二十人有点吃力，后半程基本靠自己摸索。',NULL,'2026-05-12T14:37:59+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_fc7afde','venue_pottery_025','行政小赵',4,'放了轻音乐，氛围松弛，同事之间话也多了起来。有一件在窑里裂了，店家重做了一个补给我们。胡同里的院子，出租车只能停到路口。',NULL,'2026-06-12T13:52:11+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_xead791','venue_pottery_025','团建负责人',5,'因为人数临时减了五个多退了对应的材料费。卫生间在楼道公用，不太方便。当场就给开了电子发票抬头信息核对得很仔细。在小区里面，第一次去要绕一圈，建议提前发定位。',NULL,'2026-06-26T16:04:41+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_df472db','venue_pottery_026','匿名用户',4,'桌椅高度不合适，站着做腰有点酸。围绕第二千零五十八条静置一夜小白楼店·匿名用户，当时的摘要是“问了能不能开培…说没有这个类目”。定金交了就不退，条款写在小字里，签之前一定要看。泥料细腻不扎手，做完洗手很快就干净了。',NULL,'2026-06-04T11:51:59+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_ab971f1','venue_pottery_026','云中飞鸟',4,'通风一般，釉料味道散得慢。订的餐盒准时到，独立包装，分餐方便。','休息区','2026-05-23T16:04:28+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_d89b3da','venue_pottery_027','津门小李',5,'放了轻音乐，氛围松弛，同事之间话也多了起来。门口不好停车，我们停到隔壁写字楼地库了，两小时十块。',NULL,'2026-05-24T20:24:28+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_z2d86f3','venue_pottery_027','南开的猫',5,'桌椅高度不合适，站着做腰有点酸。茶歇只有饼干和速溶咖啡，比较简单。成品上釉是老师统一做的，我们只挑颜色。当天下雨来不了改到下周只补了差价。',NULL,'2026-06-10T13:02:17+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_vf72df5','catering_pool_028','市场部Amy',4,'素食那份只有沙拉，希望能加点主食。合同里写清了忌口条款，比口头承诺放心。',NULL,'2026-05-28T22:36:00+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_y7ad7ba','catering_pool_028','团建负责人',5,'素食那份只有沙拉，希望能加点主食。起送数是二十份，人少要凑单。',NULL,'2026-05-31T17:24:22+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_v87e533','venue_pottery_029','老张头',3,'第二千零六十四条津陶轩五大道店·老张头，条目写下“会再来但下次要…要提前确认发票”。烧完颜色和挑的色卡差挺多，老师提前打过预防针。在小区里面，第一次去要绕一圈，建议提前发定位。','釉色色卡','2026-05-17T12:23:14+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_v49939f','venue_pottery_029','采购老刘',5,'退改政策口头说得松，白纸黑字是另一套。没有餐饮服务我们自己订的外卖。在商场四层，跟着扶梯上去就能看到。','拉坯现场','2026-05-26T11:42:38+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_v0be4e1','service_pool_030','匿名用户',3,'布置比约定时间晚了半小时，好在没影响开场。开培训费，说没有这个类目。沿街店面，导航能直接到，但招牌小容易走过。组织起来比想象中省心，对接人回复快。','设备摆位','2026-05-23T15:47:11+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_b7c5aaf','service_pool_030','陶艺初学者',5,'查看第二千零六十七条拍摄记录室服务部·陶艺初学者时，摘要栏保留“发票类目写的是…时被要求补说明”。当天下雨来不了改到下周只补了差价。现场引导两个人，二十多人的场足够。沿街店面导航能直接到但招牌小容易走过。',NULL,'2026-05-20T14:41:00+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_wd0dbd1','service_pool_031','预算有限',4,'布置比约定时间晚了半小时，好在没影响开场。胡同里的院子出租车只能停到路口。前台一开始说只收微信个人转账，坚持要对公才换的账户。',NULL,'2026-06-28T16:59:17+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_x3ce4dc','service_pool_031','爱做手工的会计',4,'同事反馈想多做一会儿，时间可以再放宽半小时。对公打款和刷公司卡都支持，没有让走个人码。开的是会务服务费发票，财务认。',NULL,'2026-05-08T09:36:59+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_uc2d770','venue_pottery_032','法务小孙',5,'订的餐盒准时到，独立包装，分餐方便。开的是文化体验服务费，走对公转账，财务那边顺利报销了。老师讲话声音小，后排听不太清，建议配个小蜜蜂。在小区里面第一次去要绕一圈建议提前发定位。',NULL,'2026-05-10T21:58:38+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_d3216cb','venue_pottery_032','市场部Amy',4,'只能开材料销售的发票，我们财务不认，最后自己贴的。采光好，白天不用开灯拍照都好看。二楼还有一间独立房间，团队包场后互不打扰。第二千零七十一条五感陶艺五大道店·市场部Amy，旧记录概括为“成品上釉是老师…的我们只挑颜色”。',NULL,'2026-06-27T17:59:11+08:00');
