INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_c866f48','venue_pottery_033','行政小赵',4,'定金交了就不退，条款写在小字里，签之前一定要看。老师提醒了戴手套和挽袖子，安全提示做得到位。开培训费，说没有这个类目。','作品出窑','2026-05-15T09:41:50+08:00');
