INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_af2756c','catering_pool_046','爱做手工的会计',4,'查看第二千零九十八条简餐日记·爱做手工的会计时，摘要栏保留“对公打款和刷公…没有让走个人码”。起送数是二十份，人少要凑单。取消要扣百分之三十比同行严一些。饮品分装到瓶里，比大桶自取干净。',NULL,'2026-06-12T18:23:44+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_yc6f8a9','catering_pool_046','沉默的大多数',4,'合同里写清了忌口条款，比口头承诺放心。第二千零九十九条简餐日记·沉默的大多数，旧记录概括为“当场就给开了电…息核对得很仔细”。因为人数临时减了五个多退了对应的材料费。围绕第二千零九十九条简餐日记·沉默的大多数，当时的摘要是“性价比一般胜在…般胜在离公司近”。',NULL,'2026-06-27T12:59:56+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_wd06614','venue_pottery_047','老张头',4,'有两件没烧成，退了对应的材料钱。茶歇只有饼干和速溶咖啡，比较简单。放了轻音乐，氛围松弛，同事之间话也多了起来。',NULL,'2026-06-21T18:46:31+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_x6b8a1a','venue_pottery_047','津门小李',4,'素烧和釉烧要分两次，周期比想象中长。定金两千八，比周边几家都低。茶歇只有饼干和速溶咖啡，比较简单。',NULL,'2026-06-22T09:47:59+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_edb8701','catering_pool_048','设计部小张',5,'素食那份只有沙拉，希望能加点主食。合同和发票信息一次就填对了，行政很省心。',NULL,'2026-06-27T17:51:11+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_z52f2c9','catering_pool_048','行政小赵',5,'定金两千八，比周边几家都低。整体是这半年团建里评价最高的一次。',NULL,'2026-06-15T22:44:47+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_bb61c9a','service_pool_049','沉默的大多数',3,'提前三天改期没收费，态度挺好。票，我们财务不认最后自己贴的。开的是会务服务费发票，财务认。分组任务节奏舒缓，新同事在共同整理材料时很快熟悉起来。',NULL,'2026-06-22T14:42:00+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_d6f7976','service_pool_049','法务小孙',4,'老师用开放式示范带动交流，参与者可以随时休息或旁观。第二千一百零五条灯光音响小组小白楼店·法务小孙，条目写下“问了能不能开培…说没有这个类目”。',NULL,'2026-06-08T22:33:28+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_b93a39d','venue_pottery_050','爱喝茶的程序员',5,'查看第二千一百零六条青泥堂陶艺空间·爱喝茶的程序员时，摘要栏保留“问了能不能开培…说没有这个类目”。场地标称容纳三十人但算上放包和作品架二十五人就已经很满。老师提醒了戴手套和挽袖子，安全提示做得到位。门口不好停车我们停到隔壁写字楼地库了两小时十块。','场地全景','2026-06-07T13:11:03+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_x585d7b','venue_pottery_050','法务小孙',5,'第二千一百零七条青泥堂陶艺空间·法务小孙，旧记录概括为“发票类目写的是…时被要求补说明”。烧制排期赶上旺季往后延了一周。',NULL,'2026-05-28T10:46:03+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_u940f79','venue_pottery_051','匿名用户',4,'空间比照片上小一圈，十五人以内体验最好。结束后发了作品照片，留了个念想。轻餐是三明治和沙拉标了配料不吃牛羊肉的同事有单独的份。费，走对公转账财务那边顺利报销了。',NULL,'2026-05-11T18:02:17+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_d2d605b','venue_pottery_051','法务小孙',4,'作品底部帮我们刻了编号，不用写名字也能对上。提前三天改期没收费态度挺好。釉料桶没有标成分，问了才知道含铅的那几款不给团队用。',NULL,'2026-06-06T22:52:25+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_a95aa72','service_pool_052','实习生小周',5,'定金交了就不退条款写在小字里签之前一定要看。围绕第二千一百十条活动搭建工坊中心·实习生小周，当时的摘要是“对公打款和刷公…没有让走个人码”。','指示牌','2026-05-28T19:57:22+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_v464f2d','service_pool_052','设计部小张',4,'整体是这半年团建里评价最高的一次。需要提前报备人员名单进楼。因为人数临时减了五个多退了对应的材料费。沿街店面导航能直接到但招牌小容易走过。',NULL,'2026-06-21T20:11:11+08:00');
