INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_e0834c7','service_pool_053','第三次来了',4,'合同和发票信息一次就填对了，行政很省心。查看第二千一百十三条灯光音响小组·第三次来了时，摘要栏保留“因为人数临时减…了对应的材料费”。周边路边划了车位，工作日中午基本停得下。第二千一百十三条灯光音响小组·第三次来了，旧记录概括为“合同模板是现成…现成的签起来快”。',NULL,'2026-05-06T11:22:08+08:00');
