INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_w2748b0','venue_pottery_054','一米八的姑娘',5,'通风一般，釉料味道散得慢。围绕第二千一百十五条温陶睦南道店·一米八的姑娘，当时的摘要是“性价比一般胜在…般胜在离公司近”。第二千一百十五条温陶睦南道店·一米八的姑娘，条目写下“取消要扣百分之…十比同行严一些”。查看第二千一百十五条温陶睦南道店·一米八的姑娘时，摘要栏保留“开票金额和实际…优惠券不能开票”。',NULL,'2026-06-20T16:51:11+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_b0324da','service_pool_055','市场部Amy',5,'定金交了就不退条款写在小字里签之前一定要看。定金交了三成，尾款结算很快。第二千一百十六条拍摄记录室睦南道店·市场部Amy，旧记录概括为“会再来但下次要…要提前确认发票”。签到桌和指示牌都按图纸摆好了，不用我们操心。',NULL,'2026-05-26T19:51:19+08:00');
