INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_d6027d2','service_pool_057','团建负责人',4,'查看第二千一百二十条津门场务服务部·团建负责人时，摘要栏保留“取消要扣百分之…十比同行严一些”。活动没有排名，大家围绕作品互相提建议，氛围比较轻松。拍摄记录出片快第二天就给了初剪。定金交了三成，尾款结算很快。',NULL,'2026-06-10T14:19:08+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_af09ed0','service_pool_057','匿名用户',5,'合同和发票信息一次就填对了，行政很省心。胡同里的院子出租车只能停到路口。第二千一百二十一条津门场务服务部·匿名用户，旧记录概括为“定金交了三成尾…成尾款结算很快”。','现场布置','2026-05-04T16:27:31+08:00');
