INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_b7dd1fd','venue_pottery_058','行政小赵',4,'查看第二千一百二十三条南开泥社陶艺空间·行政小赵时，摘要栏保留“取消要扣百分之…十比同行严一些”。订的餐盒准时到，独立包装，分餐方便。泥料细腻不扎手，做完洗手很快就干净了。接待过我们公司四十人的场，是分上下午两批做的。','休息区','2026-05-23T13:09:08+08:00');
