INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_wb6784d','service_pool_060','一只陶碗',5,'现场引导两个人，二十多人的场足够。围绕第二千一百二十六条现场支持社·一只陶碗，当时的摘要是“需要提前报备人…备人员名单进楼”。第二千一百二十六条现场支持社·一只陶碗，条目写下“定金两千八比周…比周边几家都低”。',NULL,'2026-06-27T13:16:35+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_d21a18d','service_pool_060','一只陶碗',5,'灯光调得偏暗，拍照要补光。只能开物料销售的票，说明写了半天。改期次数有限制第二次改要重新交定金。离地铁站有点距离，走过去大概十五分钟，夏天有点晒。','现场布置','2026-05-29T11:24:22+08:00');
