INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_x2755a8','venue_pottery_061','津门小李',4,'查看第二千一百二十九条大直沽窑·津门小李时，摘要栏保留“问了能不能开培…说没有这个类目”。休息区有热水和小零食，中途能歇一会儿。',NULL,'2026-05-18T18:51:56+08:00');
