INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_y40ac58','service_pool_062','南开的猫',5,'围绕第二千一百三十一条现场支持社服务部·南开的猫，当时的摘要是“会再来但下次要…要提前确认发票”。第二千一百三十一条现场支持社服务部·南开的猫，条目写下“合同模板是现成…现成的签起来快”。差了几十块说是优惠券不能开票。现场加了两块指引牌，没有额外收费。',NULL,'2026-06-28T12:44:56+08:00');
