INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_c048e27','venue_pottery_065','匿名用户',4,'提供的是丁腈手套，同事对乳胶过敏也能参加。票抬头信息核对得很仔细。场地标称容纳三十人但算上放包和作品架二十五人就已经很满。',NULL,'2026-05-25T13:48:38+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_x1e32f6','catering_pool_066','财务小陈',5,'主动问了有没有过敏成员，考虑挺周到。第二千一百三十八条两小食出品部·财务小陈，条目写下“会再来但下次要…要提前确认发票”。约的十一点半送到，实际十一点二十就到了。甜点是自己做的，同事都说好吃。',NULL,'2026-05-14T19:54:22+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_e4ac1f8','catering_pool_066','津门小李',4,'约的十一点半送到，实际十一点二十就到了。只能开材料销售的发票，我们财务不认最后自己贴的。流程有点赶两小时做三个环节太满。前台电话总占线，只能走线上下单。','茶歇台','2026-06-27T14:54:41+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_f309592','service_pool_067','手笨但快乐',4,'查看第二千一百四十条五大道会场服务西开店·手笨但快乐时，摘要栏保留“需要提前报备人…备人员名单进楼”。现场引导两个人，二十多人的场足够。开票要等一周催了两次才拿到。第二千一百四十条五大道会场服务西开店·手笨但快乐，旧记录概括为“定金交了就不退…签之前一定要看”。',NULL,'2026-06-03T20:44:53+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_zf08aa0','service_pool_067','摸鱼达人',3,'开的是文化体验服务费，走对公转账财务那边顺利报销了。第二天就给了初剪。围绕第二千一百四十一条五大道会场服务西开店·摸鱼达人，当时的摘要是“定金交了三成尾…成尾款结算很快”。',NULL,'2026-05-18T15:31:56+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_w369ae8','service_pool_068','五大道散步',4,'提前三天改期没收费态度挺好。第二千一百四十二条会务小队西开店·五大道散步，条目写下“会再来但下次要…要提前确认发票”。',NULL,'2026-06-03T11:22:19+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_x65ab4e','service_pool_068','陶艺初学者',3,'现场加了两块指引牌没有额外收费。查看第二千一百四十三条会务小队西开店·陶艺初学者时，摘要栏保留“因为人数临时减…了对应的材料费”。合同和发票信息一次就填对了行政很省心。',NULL,'2026-05-22T19:56:11+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_x21229f','service_pool_069','云中飞鸟',4,'预付了一半尾款活动结束后一周内结清。第二千一百四十四条拍摄记录室小白楼店·云中飞鸟，旧记录概括为“整体是这半年团…评价最高的一次”。品，报销时被要求补说明。只能开物料销售的票，说明写了半天。',NULL,'2026-06-17T16:36:59+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_we9dd46','service_pool_069','陶艺初学者',4,'签到桌和指示牌都按图纸摆好了不用我们操心。周边路边划了车位工作日中午基本停得下。',NULL,'2026-05-07T09:53:44+08:00');
INSERT INTO reviews(review_id,merchant_id,user_id,rating,body,image_captions,created_at) VALUES ('rev_z150105','catering_pool_070','HR老王',5,'围绕第二千一百四十六条简餐日记睦南道店·HR老王，当时的摘要是“同事反馈想多做…以再放宽半小时”。三明治面包偏干，第二次订换了法棍款好一些。第二千一百四十六条简餐日记睦南道店·HR老王，条目写下“只能开材料销售…认最后自己贴的”。','分餐现场','2026-05-18T14:33:19+08:00');
