INSERT INTO deals(deal_id,merchant_id,title,description,price_minor,list_price_minor,serves,valid_until,status) VALUES ('deal_service_pool_226','service_pool_226','会务物料支持','查看第二千六百八十九条和平活动服务·会务物料支持时，摘要栏保留“含指示牌签到桌…引导按半天计费”。第二千六百八十九条和平活动服务·会务物料支持，旧记录概括为“仅能开具材料销…材料销售类发票”。围绕第二千六百八十九条和平活动服务·会务物料支持，当时的摘要是“当日预约需电话…需电话确认余位”。定金见问答页说明。第二千六百八十九条和平活动服务·会务物料支持，条目写下“含围裙与手套等…手套等基础防护”。',476400,642100,25,'2026-06-01','active');
